// Values used to reference table checksums to recompute them after values are
// changed during table generation.
pub const TABLE_HEADER_CHECKSUM_OFFSET: usize = 9;
pub const TABLE_HEADER_CHECKSUM_LEN: usize = 1;

#[derive(
    Clone, Copy, Debug, Default, Eq, PartialEq, Hash, Serialize, Deserialize,
)]
pub enum AcpiVariant {
    #[default]
    V0,
}

// Internal values shared across tables.

// Values inherited from the original EDK2 static tables. They could be set to
// Propolis-specific values in the future.
const OEM_ID: &[u8; 6] = b"OVMF  ";
const OEM_TABLE_ID: &[u8; 8] = b"OVMFEDK2";
const OEM_REVISION: u32 = 0x20130221;

// IRQ used for SCI interrupts.
pub const SCI_IRQ: u8 = 0x9;

// IRQs used to handle PCI interrupts.
const PCI_LINK_IRQS: [u8; 4] = [0x05, SCI_IRQ, 0x0a, 0x0b];

// VIOAPIC_BASE in bhyve.
const IO_APIC_ADDR: u32 = 0xfec0_0000;
// VIOAPIC_SIZE in bhyve.
const IO_APIC_LEN: u32 = 0x1000;

// DEFAULT_APIC_BASE in bhyve source code.
const LOCAL_APIC_ADDR: u32 = 0xfee0_0000;
// PAGE_SIZE (4096) in bhyve, but this value was inherited from EDK2.
const LOCAL_APIC_LEN: u32 = 0x10_0000;

// Register used for PCI hotplug. This value was chosen to match QEMU and the
// original EDK2 ACPI tables.
//
// Refer to the `piix4_acpi_system_hot_add_init` function in QEMU for more
// information.
const GPE0_BLK_ADDR: u16 = 0xafe0;
const GPE0_BLK_LEN: u8 = 4;

// List of ACPI general-purpose events (GPEs) handled by Propolis.
//
// When adding a new GPE, ensure it doesn't conflict with any of the existing
// events (even if it has a different trigger).
#[derive(Clone, Copy, Debug)]
pub enum Gpe {
    PciHotplug,
}
impl Gpe {
    pub const fn event(self) -> gpe::Event {
        match self {
            Gpe::PciHotplug => gpe::Event::new(1, gpe::Trigger::Edge),
        }
    }
}

pub struct Acpi {
    // The SCI state can be driven by multiple inputs that OR'ed to determine
    // if an interrupt should happen, so model it as an OrGate and hand out new
    // inputs for components that connect to the SCI pin.
    //
    // Refer to Fig. 4.3 of the ACPI spec. v6.6 for more information.
    sci_gate: Arc<OrGate>,

    // Register block for general-purpose events.
    gpe0: gpe::RegisterBlock,
}

impl Acpi {
    pub fn create(sci_pin: Arc<dyn IntrPin>) -> Arc<Self> {
        let sci_gate = OrGate::new(sci_pin);

        let gpe0_sci_pin = sci_gate.new_input();
        let gpe0 = gpe::RegisterBlock::new(
            GPE0_BLK_ADDR,
            GPE0_BLK_LEN.into(),
            0,
            gpe0_sci_pin,
        );

        Arc::new(Self { sci_gate, gpe0 })
    }

    pub fn attach(self: &Arc<Self>, pio: &PioBus) {
        let this = Arc::clone(self);

        let gpe0_piofn =
            Arc::new(move |port: u16, rwo: RWOp| this.gpe0.pio_rw(port, rwo))
                as Arc<PioFn>;

        pio.register(GPE0_BLK_ADDR, GPE0_BLK_LEN.into(), gpe0_piofn).unwrap();
    }

    pub fn pci_hotplug(&self) {
        self.gpe0.trigger(Gpe::PciHotplug.event());
    }

    pub fn sci_pin(&self) -> Arc<dyn IntrPin> {
        self.sci_gate.new_input()
    }
}

impl Lifecycle for Acpi {
    fn type_name(&self) -> &'static str {
        "acpi"
    }
    fn reset(&self) {
        self.gpe0.reset();
    }
    fn migrate(&self) -> Migrator<'_> {
        Migrator::Multi(self)
    }
}

impl MigrateMulti for Acpi {
    fn export(
        &self,
        output: &mut PayloadOutputs,
        ctx: &MigrateCtx,
    ) -> Result<(), MigrateStateError> {
        MigrateMulti::export(&self.gpe0, output, ctx)?;
        Ok(())
    }

    fn import(
        &self,
        offer: &mut PayloadOffers,
        ctx: &MigrateCtx,
    ) -> Result<(), MigrateStateError> {
        MigrateMulti::import(&self.gpe0, offer, ctx)?;
        Ok(())
    }
}

#[cfg(test)]
mod test {
    use super::*;
    use crate::intr_pins::test::TestPin;
    use crate::migrate::test::MigrationDriver;

    #[test]
    fn migrate() {
        let expected_gpe0_sts = [
            0b0101_0000, // STS[0]
            0b0010_1000, // STS[1]
        ];
        let expected_gpe0_en = [
            0b0101_0100, // EN[0]
            0b1010_1000, // EN[1]
        ];

        // Populate source.
        let src = {
            let pin = Arc::new(TestPin::new());
            let src = Acpi::create(pin.clone());

            (0..2).for_each(|i| {
                // Platform raises STS bits.
                gpe::test::raise_sts(&src.gpe0, i, expected_gpe0_sts[i]);
                // Guest enables EN bits.
                gpe::test::pio_write(
                    &src.gpe0,
                    gpe::Register::En(i),
                    expected_gpe0_en[i],
                );
            });

            src
        };

        // Create and migrate destination.
        let pin = Arc::new(TestPin::new());
        let dest = Acpi::create(pin.clone());
        MigrationDriver::new().migrate(src.as_ref(), dest.as_ref());

        (0..2).for_each(|i| {
            assert_eq!(
                gpe::test::pio_read(&dest.gpe0, gpe::Register::Sts(i)),
                expected_gpe0_sts[i],
                "unexpected value for STS[{i}]",
            );
            assert_eq!(
                gpe::test::pio_read(&dest.gpe0, gpe::Register::En(i)),
                expected_gpe0_en[i],
                "unexpected value for EN[{i}]",
            );
        });
        assert!(pin.is_asserted());
    }
}
